'use strict';

// Image3 响应解析：从官方同步响应提取结果图片 URL。

function responseError(code, message) {
  const error = new Error(message);
  error.code = code;
  error.status = 502;
  return error;
}

// 解析官方同步响应，返回图片 URL 数组（保持顺序）。
function parseImage3Response(data) {
  if (!data || typeof data !== 'object') {
    throw responseError('IMAGE3_RESPONSE_INVALID', '上游响应无效');
  }
  const content = data?.output?.choices?.[0]?.message?.content;
  if (!Array.isArray(content)) {
    throw responseError('IMAGE3_RESPONSE_INVALID', '上游响应缺少结果内容');
  }
  const urls = [];
  for (const item of content) {
    if (item && typeof item.image === 'string' && item.image) {
      urls.push(item.image);
    }
  }
  if (urls.length === 0) {
    throw responseError('IMAGE3_RESPONSE_NO_IMAGE', '上游响应未解析到图片');
  }
  return urls;
}

module.exports = { parseImage3Response };
